const fillings=[['韭菜鸡蛋','Poireau et œuf'],['鲜肉','Porc'],['牛肉','Bœuf']];
const productFillings={
  A1:[['韭菜鸡蛋','Poireau et œuf']],
  A2:[['猪肉白菜','Porc et chou'],['鲜肉','Porc'],['韭菜猪肉','Porc et poireau']],
  A3:[['红油牛肉包','Bao au bœuf pimenté'],['牛肉鲜肉包','Bao au bœuf frais']]
};
const cooking={包子:[['清蒸','Vapeur'],['煎包','Poêlé']],饺子:[['水煮','À l’eau'],['清蒸','Vapeur'],['煎饺','Poêlés']]};
let cart=[],selection={},service='堂食';
const choice=document.querySelector('#choice-dialog'),choiceOptions=document.querySelector('#choice-options'),paymentDialog=document.querySelector('#payment-dialog'),receipt=document.querySelector('#receipt-dialog');
const euro=value=>`${Number(value).toFixed(2).replace('.',',')} €`;
const total=()=>cart.reduce((sum,item)=>sum+item.price*item.qty,0);
function productFrom(button){return {category:button.dataset.category,code:button.dataset.code,dish:button.dataset.dish,fr:button.dataset.fr,price:Number(button.dataset.price)}}
function renderOptions(values,handler){choiceOptions.innerHTML='';values.forEach(([zh,fr])=>{const button=document.createElement('button');button.type='button';button.innerHTML=`${zh}<small>${fr}</small>`;button.onclick=()=>handler(zh,fr);choiceOptions.append(button)})}
function addSelection(){const item={...selection,qty:1};const same=cart.find(entry=>entry.code===item.code&&entry.filling===item.filling&&entry.style===item.style);if(same)same.qty+=1;else cart.push(item);choice.close();renderCart()}
function chooseCooking(){document.querySelector('#choice-step').textContent='步骤 2 / 2 · 选择做法';document.querySelector('#choice-title').textContent='蒸、煎还是水煮？';document.querySelector('#choice-product').textContent=`${selection.code} · ${selection.dish} · ${selection.filling}`;renderOptions(cooking[selection.category],(zh,fr)=>{selection.style=zh;selection.styleFr=fr;addSelection()})}
function chooseProduct(button){selection=productFrom(button);if(selection.category==='粥品'){addSelection();return}document.querySelector('#choice-step').textContent='步骤 1 / 2 · 选择馅料';document.querySelector('#choice-title').textContent='请选择馅料';document.querySelector('#choice-product').textContent=`${selection.code} · ${selection.dish} · ${selection.fr}`;renderOptions(productFillings[selection.code]||fillings,(zh,fr)=>{selection.filling=zh;selection.fillingFr=fr;chooseCooking()});choice.showModal()}
function renderCart(){const holder=document.querySelector('#cart-items');document.querySelector('#cart-count').textContent=`${cart.reduce((sum,item)=>sum+item.qty,0)} 件`;holder.innerHTML=cart.length?cart.map((item,index)=>`<div class="cart-row"><div><strong><b>${item.code}</b> · ${item.dish}</strong><small>${item.fr}${item.filling?` · ${item.filling} / ${item.fillingFr} · ${item.style} / ${item.styleFr}`:''}</small></div><div><strong>${euro(item.price*item.qty)}</strong><div class="quantity"><button data-change="-1" data-index="${index}">−</button><b>${item.qty}</b><button data-change="1" data-index="${index}">＋</button><button class="remove" data-remove="${index}">删除</button></div></div></div>`).join(''):'<p class="empty">请选择商品<br><small>Votre panier est vide</small></p>';holder.querySelectorAll('[data-change]').forEach(button=>button.onclick=()=>{const item=cart[Number(button.dataset.index)];item.qty+=Number(button.dataset.change);if(item.qty<1)cart.splice(Number(button.dataset.index),1);renderCart()});holder.querySelectorAll('[data-remove]').forEach(button=>button.onclick=()=>{cart.splice(Number(button.dataset.remove),1);renderCart()});document.querySelector('#cart-total').textContent=euro(total());document.querySelector('#pay-button').disabled=!cart.length}
function setCategory(category){const meta={包子:['A · BAO','包子','点击包子后选择馅料与清蒸或煎包'],饺子:['B · DUMPLINGS','饺子','点击饺子后选择馅料与水煮、清蒸或煎饺'],粥品:['C · CONGEE','粥品','粥品为完整单品，点击即可加入购物车']}[category];document.querySelector('#category-code').textContent=meta[0];document.querySelector('#category-title').textContent=meta[1];document.querySelector('.menu-head span').textContent=meta[2];document.querySelectorAll('.product-card').forEach(card=>card.hidden=card.dataset.category!==category);document.querySelectorAll('.category').forEach(button=>button.classList.toggle('active',button.dataset.category===category))}
function completePayment(method){const key='baoDumplingOrders',auditKey='baoDumplingAudit',pickupKey='baoDumplingPickupCounter',orders=JSON.parse(localStorage.getItem(key)||'[]'),now=new Date(),number=(Number(localStorage.getItem(pickupKey)||0)%999)+1,pickup=String(number).padStart(3,'0'),amount=total(),id=`BD-${now.toISOString().slice(0,10).replaceAll('-','')}-${pickup}`;orders.push({id,pickupNumber:pickup,day:now.toDateString(),month:now.toISOString().slice(0,7),time:now.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}),items:cart.map(item=>({...item})),total:amount,paidTotal:amount,status:'paid',payment:method,service,source:'self',kitchenStatus:'new',corrections:[]});localStorage.setItem(key,JSON.stringify(orders));localStorage.setItem(pickupKey,String(number));const audit=JSON.parse(localStorage.getItem(auditKey)||'[]');audit.push({time:now.toLocaleString('fr-FR'),action:'自助点餐付款',details:`${id} · ${euro(amount)} · ${method}`});localStorage.setItem(auditKey,JSON.stringify(audit.slice(-250)));cart=[];paymentDialog.close();document.querySelector('#pickup-number').textContent=pickup;document.querySelector('#receipt-total').textContent=`${service} · ${method} · ${euro(amount)}`;receipt.showModal();renderCart()}
document.querySelectorAll('.product-card').forEach(button=>button.onclick=()=>chooseProduct(button));document.querySelectorAll('.category').forEach(button=>button.onclick=()=>setCategory(button.dataset.category));document.querySelectorAll('.service-choice').forEach(button=>button.onclick=()=>{service=button.dataset.service;document.querySelectorAll('.service-choice').forEach(item=>item.classList.toggle('active',item===button))});document.querySelector('#clear-button').onclick=()=>{cart=[];renderCart()};document.querySelector('#pay-button').onclick=()=>{if(cart.length)paymentDialog.showModal()};document.querySelectorAll('[data-method]').forEach(button=>button.onclick=()=>completePayment(button.dataset.method));renderCart();setCategory('包子');
